// TO_VALIDATE: placeholder extraction logic only.
// Rebuild these regexes against a real Fresha booking-confirmation email
// before trusting this node. Do not use in production unvalidated.
const body = $input.item.json.text || $input.item.json.html || '';
const subject = $input.item.json.subject || '';

// PLACEHOLDER patterns - guesses at a typical Fresha email format
const clientNameMatch = body.match(/(?:Client|Customer|Booked by)[:\s]+([A-Za-z '-]+)/i);
const serviceMatch = body.match(/(?:Service|Appointment)[:\s]+([A-Za-z0-9 ,'-]+)/i);
const dateTimeMatch = body.match(/(?:Date|When)[:\s]+([A-Za-z0-9:, -]+)/i);
const refMatch = body.match(/(?:Booking (?:ref|reference|id))[:\s#]+([A-Za-z0-9-]+)/i);

const clientName = clientNameMatch ? clientNameMatch[1].trim() : null;
const service = serviceMatch ? serviceMatch[1].trim() : null;
const appointmentAt = dateTimeMatch ? dateTimeMatch[1].trim() : null;
const bookingRef = refMatch ? refMatch[1].trim() : null;

const parseOk = Boolean(clientName && service && appointmentAt);

return [{
  json: {
    clientName,
    service,
    appointmentAt,
    bookingRef: bookingRef || `NOREF-${Date.now()}`,
    subject,
    parseOk
  }
}];

// TO_VALIDATE: 48h escalation window is from the source research,
// not yet confirmed directly with the owner - adjust ESCALATION_HOURS once she confirms.
const ESCALATION_HOURS = 48;
const now = new Date();

const overdue = $input.all().filter(item => {
  const status = item.json['Status'];
  const sentAt = item.json['Instructions Sent At'];
  if (!sentAt) return false;
  if (status !== 'Instructions Sent' && status !== 'Reminder Sent') return false;
  const hoursSince = (now - new Date(sentAt)) / (1000 * 60 * 60);
  return hoursSince >= ESCALATION_HOURS;
});

return overdue;
